oxy_webhelp_navlinks = {"tocId-d39536e67150":{"topics":[{"title":"Multitenancy with <span class=\"ph\">RSC<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Rubrik Security Cloud<\/span> multitenancy uses a multi-account management framework that         enables a single primary <span class=\"ph\">Rubrik Security Cloud<\/span> account to provision, manage, and monitor         multiple <span class=\"ph\">Rubrik Security Cloud<\/span> environments. The architecture is designed to support both         shared infrastructure and strict physical isolation.<\/p>","href":"saas\/mt_multitenancy.html","attributes":{"data-id":"mt_multitenancy"},"menu":{"hasChildren":false},"tocID":"mt_multitenancy-d39536e67156","topics":[]},{"title":"Tenant comparison","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Rubrik Security Cloud<\/span> offers various multitenancy models to support different         requirements for resource isolation, administrative autonomy, and access to advanced         security applications.<\/p>","href":"saas\/mt_tenant_comparison.html","attributes":{"data-id":"mt_tenant_comparison"},"menu":{"hasChildren":false},"tocID":"mt_tenant_comparison-d39536e67177","topics":[]},{"title":"Dedicated tenants","shortdesc":"<p class=\"shortdesc\">Dedicated <span class=\"ph\">Rubrik Security Cloud<\/span> tenants provide Managed Service Providers with         physically isolated <span class=\"ph\">Rubrik Security Cloud<\/span> instances for their clients, ensuring complete         data separation and feature parity across security applications.<\/p>","href":"saas\/mt_ded_tenant.html","attributes":{"data-id":"mt_ded_tenant"},"menu":{"hasChildren":true},"tocID":"mt_ded_tenant-d39536e67190","next":"mt_ded_tenant-d39536e67190"},{"title":"Shared clusters","shortdesc":"<p class=\"shortdesc\">Shared clusters provide software-enforced isolation between dedicated tenants         provisioned on a single <span class=\"ph\">RSC<\/span> cluster, ensuring data separation and feature         parity while maximizing hardware ROI.<\/p>","href":"saas\/mt_sc_shared_clusters.html","attributes":{"data-id":"mt_sc_shared_clusters"},"menu":{"hasChildren":true},"tocID":"mt_sc_shared_clusters-d39536e67451","next":"mt_sc_shared_clusters-d39536e67451"},{"title":"Network Connectors","shortdesc":"<p class=\"shortdesc\">Network Connectors enable Rubrik to back up and recover workloads in environments         where network segmentation, NAT, or overlapping IP address ranges prevent the Rubrik cluster         from directly reaching tenant workloads.<\/p>","href":"saas\/mt_dt_nc_about.html","attributes":{"data-id":"mt_dt_nc_about"},"menu":{"hasChildren":true},"tocID":"mt_dt_nc_about-d39536e67634","next":"mt_dt_nc_about-d39536e67634"},{"title":"Organizations","shortdesc":"<p class=\"shortdesc\">Multitenancy in <span class=\"ph\">Rubrik Security Cloud<\/span> provides logical isolation of shared         compute, storage, and network resources in such a way that each organization can only access         its own data, especially for shared infrastructure platforms.<\/p>","href":"saas\/mt_organizations.html","attributes":{"data-id":"mt_organizations"},"menu":{"hasChildren":true},"tocID":"mt_organizations-d39536e67774","next":"mt_organizations-d39536e67774"}]}};